{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be dict")
    required = ['text', 'passes', 'max_rounds']
    for k in required:
        if k not in case:
            raise ValueError(f"Missing required key: {k}")
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    if not isinstance(text, str):
        raise ValueError("text must be string")
    if not isinstance(passes, list):
        raise ValueError("passes must be list")
    if not isinstance(max_rounds, int) or max_rounds < 0:
        raise ValueError("max_rounds must be non-negative integer")
    applications = []
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            if not isinstance(p, dict):
                raise ValueError("each pass must be dict")
            if 'name' not in p or 'old' not in p or 'new' not in p:
                raise ValueError("each pass must have name, old, new")
            old = p['old']
            new = p['new']
            if not isinstance(old, str) or not isinstance(new, str):
                raise ValueError("old and new must be strings")
            if old in text:
                text = text.replace(old, new, 1)
                applications.append(p['name'])
                changed = True
        if not changed:
            return {'applications': applications, 'fixed_point': True, 'text': text}
    return {'applications': applications, 'fixed_point': False, 'text': text}"}
